#include <iostream>
#include <vector>
#include <unordered_map>
#include <numeric>
using namespace std;

const int MOD = 1000000007;

struct DSU {
    vector<int> parent, rank;

    explicit DSU(int n) : parent(n), rank(n, 0) {
        iota(parent.begin(), parent.end(), 0);
    }

    int find(int x) {
        while (x != parent[x]) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }

    void unite(int a, int b) {
        a = find(a);
        b = find(b);
        if (a == b) return;

        if (rank[a] < rank[b]) swap(a, b);
        parent[b] = a;
        if (rank[a] == rank[b]) ++rank[a];
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    DSU dsu(n);
    unordered_map<int, int> xRepresentative, yRepresentative;
    xRepresentative.reserve(n * 2);
    yRepresentative.reserve(n * 2);

    for (int i = 0; i < n; ++i) {
        int x, y;
        cin >> x >> y;

        auto [xIt, xInserted] = xRepresentative.emplace(x, i);
        if (!xInserted) dsu.unite(i, xIt->second);

        auto [yIt, yInserted] = yRepresentative.emplace(y, i);
        if (!yInserted) dsu.unite(i, yIt->second);
    }

    vector<int> componentSize(n, 0);
    vector<int> xCount(n, 0);
    vector<int> yCount(n, 0);

    for (int i = 0; i < n; ++i)
        ++componentSize[dsu.find(i)];

    for (const auto& entry : xRepresentative)
        ++xCount[dsu.find(entry.second)];

    for (const auto& entry : yRepresentative)
        ++yCount[dsu.find(entry.second)];

    vector<int> powerOfTwo(n + 2, 1);
    for (int i = 1; i < static_cast<int>(powerOfTwo.size()); ++i)
        powerOfTwo[i] = static_cast<long long>(powerOfTwo[i - 1]) * 2 % MOD;

    long long answer = 1;
    for (int i = 0; i < n; ++i) {
        if (dsu.find(i) != i) continue;

        int vertices = xCount[i] + yCount[i];
        int factor = powerOfTwo[vertices];
        if (vertices == componentSize[i] + 1)
            --factor;

        answer = answer * factor % MOD;
    }

    cout << answer << '\n';
    return 0;
}

